#include "HILNeuralChipModel.h"
namespace dnxr { void HILNeuralChipModel::setFaults(const HILNeuralChipFaults& f){faults_=f;} NeuralChipAck HILNeuralChipModel::acknowledge(const SafeNeuralStimulusCommand& c) const { NeuralChipAck a; a.packetId=c.sequenceId; a.latencyMeasuredMs=faults_.delayedAck?25.0f:faults_.variableLatencyMs; a.deviceTemperature=faults_.deviceTemperature; a.hardwareCutoffActive=faults_.hardwareCutoff; a.signedAck=!faults_.firmwareMismatch; a.feedbackAvailable=!faults_.hardwareCutoff; a.signalQuality=faults_.channelSaturation?0.25f:0.95f; a.packetAccepted=c.allowStimulusDispatch&&!faults_.hardwareCutoff&&!faults_.unsupportedChannels; a.applied=a.packetAccepted; a.notApplied=!a.applied; a.packetRejected=!a.packetAccepted; a.rejectReason=a.packetRejected?"hil_fault_rejection":""; return a; } NeuralChipFrame HILNeuralChipModel::feedback(std::uint64_t id) const { NeuralChipFrame f; f.sequenceId=id; f.channels.assign(8, faults_.feedbackNoise); f.signalQuality=faults_.channelSaturation?0.25f:0.9f; f.acquisitionLatencyMs=faults_.variableLatencyMs; return f; } }
